// Exercise ids are permanent keys (the day is looked up from the EX arrays, never parsed from the id).
// If you ever must rename an id, add  oldId:'newId'  here and existing history follows it automatically.
var ID_ALIASES={};
var SCHED_REENTRY={0:null,1:'d1',2:null,3:'d2',4:'d3',5:null,6:'d4'};
var SCHED_FULL={0:null,1:'d1',2:'d2',3:null,4:'d3',5:'d4',6:'d5'};
function getScheduleFor(d){
  var start=localStorage.getItem('pt_program_start');
  if(!start)return SCHED_FULL;
  var startDate=new Date(start+'T00:00:00');
  var t=new Date(d||new Date());
  t.setHours(0,0,0,0);
  var diffDays=Math.round((t-startDate)/(1000*60*60*24));
  return (diffDays>=0&&diffDays<14)?SCHED_REENTRY:SCHED_FULL;
}
function getCurrentSchedule(){return getScheduleFor(new Date());}
var SCHED=SCHED_FULL;
