function getCycleWeekInfo(d){
  var start=localStorage.getItem('pt_program_start');
  if(!start){
    var keys=Object.keys(load().logs).sort();
    if(!keys.length)return null;
    start=keys[0];
  }
  var sd=new Date(start+'T00:00:00');var td=new Date(d);td.setHours(0,0,0,0);
  var days=Math.floor((td-sd)/(24*60*60*1000));
  if(days<0)return null;
  var totalWeek=Math.floor(days/7);
  var cycleIdx=totalWeek%CYCLE_LENGTH;
  var cycleNum=Math.floor(totalWeek/CYCLE_LENGTH);
  var plan=WEEK_PLAN[cycleIdx];
  return{weekNum:cycleIdx+1,cycleIdx:cycleIdx,cycleNum:cycleNum,totalWeek:totalWeek,type:plan.type,sourceOffset:plan.sourceOffset||null,plan:plan,startDate:start};
}
